insert into app.figures (tenant_id, id, discipline_id, apparatus, name, level_id, difficulty, description, attention_points, prerequisites, cover_path, author_member_id, created_at) values
  ('14920634-3760-5688-8c51-ae5013b84734', '14ab30dd-b226-5dd9-962c-2e9fb524110f', 'bc92f2b5-5dde-5801-bcf3-d11ff7d1f15a', 'Cerchio', 'Seduta base', '7db35ece-1f9e-5335-afa3-7b775b7cd70b', 1, 'La posizione di partenza di quasi tutte le figure sopra la barra. Si sale dal basso con una raccolta controllata delle gambe e ci si siede sulla barra inferiore, mantenendo il busto allineato e le mani sui lati del cerchio.', array['Scapole depresse: non “appendersi” alle spalle', 'Sedersi al centro della barra per non far ruotare il cerchio', 'Espirare durante la raccolta delle ginocchia']::text[], array['Appeso attivo di 10 secondi', 'Raccolta delle ginocchia al petto']::text[], '/images/photos/cerchio-03.webp', '1a26a1a2-87fe-5dd0-99cf-c19655063b01', (current_date + -120)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'e1001b80-9862-5281-8e4c-f53cc5956be4', 'bc92f2b5-5dde-5801-bcf3-d11ff7d1f15a', 'Cerchio', 'Man in the Moon', '7db35ece-1f9e-5335-afa3-7b775b7cd70b', 2, 'Figura iconica del cerchio: il corpo si incastra in diagonale dentro il cerchio, con la schiena contro un lato e i piedi a spingere sull’altro. La tensione tra schiena e piedi crea la stabilità che permette di liberare le braccia.', array['Spingere attivamente con i piedi: la figura vive di contrasto', 'Bacino in avanti, non lasciarlo cadere sulla barra', 'Collo lungo, spalle lontane dalle orecchie']::text[], array['Seduta base', 'Salita in autonomia']::text[], '/images/photos/cerchio-12.webp', '1a26a1a2-87fe-5dd0-99cf-c19655063b01', (current_date + -110)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'd26d8e4b-ab96-5c8a-96f0-34ed713c6f72', 'bc92f2b5-5dde-5801-bcf3-d11ff7d1f15a', 'Cerchio', 'Bird’s Nest', 'db2e74da-deb6-50a8-99c4-35c6ffbbb2ec', 3, 'Il “nido d’uccello”: in sospensione sotto la barra, mani e piedi agganciati, il corpo si apre in un arco con il petto rivolto verso il pavimento. Si lavora inizialmente con l’assistenza dell’insegnante.', array['Piedi a martello sulla barra per una presa sicura', 'Aprire dalle spalle, non solo dalla zona lombare', 'Uscire sempre in modo controllato tornando in raccolta']::text[], array['Inversione controllata', 'Mobilità delle spalle', 'Seduta base']::text[], '/images/photos/cerchio-05.webp', '1a26a1a2-87fe-5dd0-99cf-c19655063b01', (current_date + -95)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'a9f63d5c-686e-5330-bd9d-a8d29ac4fff9', 'bc92f2b5-5dde-5801-bcf3-d11ff7d1f15a', 'Cerchio', 'Mermaid', 'db2e74da-deb6-50a8-99c4-35c6ffbbb2ec', 3, 'La “sirena”: appese con un ginocchio sulla barra inferiore e una mano sul lato, si allunga il corpo all’esterno del cerchio disegnando una linea morbida dalla mano al piede.', array['Ginocchio ben incastrato prima di aprire', 'Fianco attivo, evitare di collassare sul lato', 'Gamba libera lunga con punta attiva']::text[], array['Man in the Moon', 'Aggancio di ginocchio sicuro']::text[], '/images/photos/cerchio-16.webp', '1a26a1a2-87fe-5dd0-99cf-c19655063b01', (current_date + -80)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'f8fd447a-809f-5766-8ca2-0cd4f0611d8d', 'bc92f2b5-5dde-5801-bcf3-d11ff7d1f15a', 'Cerchio', 'Gazelle', 'db2e74da-deb6-50a8-99c4-35c6ffbbb2ec', 3, 'Figura elegante sotto la barra: il corpo esce dal cerchio in posizione quasi orizzontale, sostenuto da una gamba agganciata e dalle mani, mentre la gamba libera si piega dietro come in un salto di gazzella.', array['Spingere la barra lontano con le mani per allungare il busto', 'Ginocchio agganciato attivo per tutta la figura', 'Collo in linea con la colonna']::text[], array['Mermaid', 'Hip hang stabile']::text[], '/images/photos/cerchio-17.webp', '1a26a1a2-87fe-5dd0-99cf-c19655063b01', (current_date + -60)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'ec1a68e3-6776-516c-a719-7ffcf43526c0', 'bc92f2b5-5dde-5801-bcf3-d11ff7d1f15a', 'Cerchio', 'Amazon', 'db2e74da-deb6-50a8-99c4-35c6ffbbb2ec', 3, 'Figura di grande impatto scenico in cui il corpo si apre all’indietro da una seduta laterale, sostenuto dalla gamba agganciata alla barra. Richiede controllo della zona addominale e una buona apertura delle anche.', array['Aggancio della gamba saldo prima di andare indietro', 'Scendere vertebra per vertebra, senza “cadere”', 'Tenere il core attivo per la risalita']::text[], array['Seduta base', 'Mermaid']::text[], '/images/photos/cerchio-14.webp', '42c5409b-49fa-5505-a6fd-b690b2d8922e', (current_date + -45)),
  ('14920634-3760-5688-8c51-ae5013b84734', '8660f98e-382f-597a-966b-ef4ee0e75dc9', 'bc92f2b5-5dde-5801-bcf3-d11ff7d1f15a', 'Cerchio', 'Delilah', '8272b554-4a1d-50e8-b3f2-28e3bee4b909', 4, 'Spaccata inversa sospesa sotto il cerchio: una gamba aggancia la barra superiore mentre l’altra si apre in avanti. È una figura avanzata che unisce flessibilità, forza di presa e fiducia nella propria posizione.', array['Lavorare sempre con tappeto e assistenza le prime volte', 'Anche squadrate durante l’apertura', 'Mani pronte sul cerchio durante l’entrata e l’uscita']::text[], array['Gazelle', 'Spaccata a terra al 90%', 'Inversione controllata']::text[], '/images/photos/cerchio-22.webp', '42c5409b-49fa-5505-a6fd-b690b2d8922e', (current_date + -30)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'c27044ac-4440-590d-a331-23b487e1729e', 'bc92f2b5-5dde-5801-bcf3-d11ff7d1f15a', 'Cerchio', 'Spaccata nel cerchio', '8272b554-4a1d-50e8-b3f2-28e3bee4b909', 4, 'Spaccata frontale eseguita all’interno o lungo il cerchio, spesso usata come momento culminante di una coreografia. Si costruisce con un lavoro costante di flessibilità a terra.', array['Riscaldamento specifico di anche e ischiocrurali', 'Bacino frontale, ginocchia rivolte verso l’alto', 'Mai forzare l’apertura in aria oltre quella a terra']::text[], array['Delilah', 'Spaccata a terra completa']::text[], '/images/photos/cerchio-19.webp', '42c5409b-49fa-5505-a6fd-b690b2d8922e', (current_date + -12)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'e927ef23-0788-5ce1-8e30-d101bbf1db3e', 'bc92f2b5-5dde-5801-bcf3-d11ff7d1f15a', 'Cerchio', 'Back Balance', '8272b554-4a1d-50e8-b3f2-28e3bee4b909', 5, 'Equilibrio in appoggio sulla parte bassa della schiena, con il cerchio che diventa l’unico punto di contatto. Figura di grande controllo, da affrontare solo con solide basi e con l’insegnante vicino.', array['Trovare il punto di equilibrio prima di lasciare le mani', 'Sguardo fisso per stabilizzare', 'Cerchio fermo: chiedere a una compagna di stabilizzarlo']::text[], array['Amazon', 'Seduta base', 'Ottimo controllo del core']::text[], '/images/photos/cerchio-21.webp', '42c5409b-49fa-5505-a6fd-b690b2d8922e', (current_date + -5)),
  ('14920634-3760-5688-8c51-ae5013b84734', '1857519b-41ae-5811-9b06-ca9c9d5c3d55', '71d29ac5-7978-591f-84ef-fccd4893ff60', 'Tessuti', 'Foot Lock', '7db35ece-1f9e-5335-afa3-7b775b7cd70b', 1, 'La chiave di piede è la base di tutte le figure in piedi sui tessuti: il tessuto si avvolge attorno al piede e viene bloccato dall’altro piede, creando un appoggio stabile su cui stare in verticale.', array['Avvolgimento dall’esterno verso l’interno', 'Peso sul piede che blocca, non su quello avvolto', 'Verificare sempre la chiave prima di liberare le mani']::text[], array['Presa base sul tessuto', 'Salita in raccolta']::text[], '/images/photos/tessuti-24.webp', '1e2374ca-1a14-5ae7-9a5a-30bbd3e81aa3', (current_date + -115)),
  ('14920634-3760-5688-8c51-ae5013b84734', '1b7fcb41-27d6-5f81-b352-081cccee984e', '71d29ac5-7978-591f-84ef-fccd4893ff60', 'Tessuti', 'Russian Climb', '7db35ece-1f9e-5335-afa3-7b775b7cd70b', 2, 'Tecnica di arrampicata in cui il tessuto viene pinzato tra i piedi, permettendo di salire usando la spinta delle gambe e risparmiando le braccia.', array['Ginocchia al petto prima di agganciare il tessuto', 'Piede “a martello” per pinzare bene', 'Braccia lunghe sopra la testa a ogni ripetizione']::text[], array['Foot Lock', 'Appeso attivo']::text[], '/images/photos/tessuti-28.webp', '1e2374ca-1a14-5ae7-9a5a-30bbd3e81aa3', (current_date + -105)),
  ('14920634-3760-5688-8c51-ae5013b84734', '5d7a8e08-c8a0-50ea-bfbb-752038f1b7fd', '71d29ac5-7978-591f-84ef-fccd4893ff60', 'Tessuti', 'Inversione base', '7db35ece-1f9e-5335-afa3-7b775b7cd70b', 2, 'Il primo capovolgimento in aria: partendo da una presa alta si raccolgono le gambe e si porta il bacino sopra la testa, con le gambe ai lati dei due tessuti.', array['Lavorare a bassa quota finché non è automatica', 'Spinta dalle braccia, non dal collo', 'Gambe sempre in contatto con il tessuto']::text[], array['Raccolta ginocchia dall’appeso']::text[], '/images/photos/tessuti-03.webp', '1e2374ca-1a14-5ae7-9a5a-30bbd3e81aa3', (current_date + -100)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'dc94c8c8-6909-545b-9069-bd203cffaf6b', '71d29ac5-7978-591f-84ef-fccd4893ff60', 'Tessuti', 'Hip Key', 'db2e74da-deb6-50a8-99c4-35c6ffbbb2ec', 3, 'La chiave d’anca blocca il corpo in modo sicuro grazie all’avvolgimento del tessuto attorno al bacino. È il punto di partenza di moltissime figure e cadute.', array['Controllare quale gamba passa davanti al tessuto', 'Ruotare dal bacino, non dalle spalle', 'Sentire il tessuto ben teso sull’anca prima di aprire']::text[], array['Inversione base', 'Foot Lock']::text[], '/images/photos/tessuti-25.webp', '1e2374ca-1a14-5ae7-9a5a-30bbd3e81aa3', (current_date + -85)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'e895f011-67dd-5baa-be45-6ae3e9c7595b', '71d29ac5-7978-591f-84ef-fccd4893ff60', 'Tessuti', 'Crochet', 'db2e74da-deb6-50a8-99c4-35c6ffbbb2ec', 3, 'Figura di avvolgimento in cui il tessuto si aggancia alla gamba come un uncino, creando un appoggio per aprire il busto in posizioni sospese.', array['Ordine degli avvolgimenti sempre uguale', 'Gamba agganciata in flessione attiva', 'Ripassare la sequenza a terra prima di salire']::text[], array['Hip Key', 'Inversione base']::text[], '/images/photos/tessuti-12.webp', '1e2374ca-1a14-5ae7-9a5a-30bbd3e81aa3', (current_date + -70)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'fe09b2e6-5a7a-5d30-967b-bbcbbd190512', '71d29ac5-7978-591f-84ef-fccd4893ff60', 'Tessuti', 'Angel', 'db2e74da-deb6-50a8-99c4-35c6ffbbb2ec', 3, 'L’angelo: il corpo si apre in avanti sostenuto dal tessuto che passa dietro la schiena e attorno a una gamba, con le braccia che si allargano come ali.', array['Tessuto ben posizionato sotto le scapole', 'Gambe attive per non scivolare', 'Aprire le braccia solo quando la figura è stabile']::text[], array['Hip Key', 'Crochet']::text[], '/images/photos/tessuti-08.webp', '1e2374ca-1a14-5ae7-9a5a-30bbd3e81aa3', (current_date + -50)),
  ('14920634-3760-5688-8c51-ae5013b84734', '621f8e14-954f-5e4b-9cfb-567bc01b8420', '71d29ac5-7978-591f-84ef-fccd4893ff60', 'Tessuti', 'Cross Back Straddle', 'db2e74da-deb6-50a8-99c4-35c6ffbbb2ec', 4, 'I due tessuti si incrociano dietro la schiena formando un’amaca sicura: da qui le gambe si aprono in straddle e le mani possono lasciare la presa.', array['Incrocio all’altezza delle scapole, non della vita', 'Gambe avvolte per bloccare il tessuto', 'Rilasciare una mano alla volta']::text[], array['Inversione base', 'Hip Key']::text[], '/images/photos/tessuti-09.webp', '42c5409b-49fa-5505-a6fd-b690b2d8922e', (current_date + -35)),
  ('14920634-3760-5688-8c51-ae5013b84734', '4e4ee122-5306-56bb-a7e5-55bf0ed6f825', '71d29ac5-7978-591f-84ef-fccd4893ff60', 'Tessuti', 'Spaccata sospesa', '8272b554-4a1d-50e8-b3f2-28e3bee4b909', 4, 'Spaccata frontale sostenuta dai due tessuti avvolti ai piedi. Figura di grande effetto scenico, richiede flessibilità completa e controllo della chiave.', array['Chiavi di piede ben chiuse prima di aprire', 'Bacino orientato in avanti', 'Uscita sempre controllata, senza rimbalzi']::text[], array['Foot Lock', 'Spaccata a terra completa']::text[], '/images/photos/tessuti-02.webp', '42c5409b-49fa-5505-a6fd-b690b2d8922e', (current_date + -20)),
  ('14920634-3760-5688-8c51-ae5013b84734', 'fd046bab-670a-534d-9b0f-7442b7c96e09', '71d29ac5-7978-591f-84ef-fccd4893ff60', 'Tessuti', 'Star Drop', '8272b554-4a1d-50e8-b3f2-28e3bee4b909', 5, 'Prima caduta “a stella”: il corpo ruota srotolando gli avvolgimenti e si ferma in sicurezza grazie alla chiave finale. Si prova solo dopo aver verificato gli avvolgimenti con l’insegnante.', array['Controllo degli avvolgimenti con l’insegnante prima di ogni caduta', 'Corpo compatto durante la rotazione', 'Mai provare da sole senza supervisione']::text[], array['Cross Back Straddle', 'Hip Key', 'Crochet']::text[], '/images/photos/tessuti-21.webp', '42c5409b-49fa-5505-a6fd-b690b2d8922e', (current_date + -8));
