insert into app.events (tenant_id, id, type, title, description, date, start_time, end_time, location, image_path, capacity, signup_deadline, is_demo) values
  ('14920634-3760-5688-8c51-ae5013b84734', '38b0d494-6e5e-5ce1-9de7-97767a653582', 'workshop', 'Workshop “Linee e flessibilità”', 'Un pomeriggio dedicato alla mobilità attiva di anche e spalle, con esercizi a terra e applicazioni su cerchio e tessuti. Aperto a tutti i livelli.', (current_date + 9), '15:00', '17:30', 'Sala Luna — Viale Verdi 186, Modena', '/images/photos/tessuti-05.webp', 14, (current_date + 7), true),
  ('14920634-3760-5688-8c51-ae5013b84734', '64e297ee-2299-50c3-94a8-57ab06aad45e', 'show', 'Spettacolo di Natale “Sospese tra le stelle”', 'Il saggio-spettacolo di fine anno: coreografie di gruppo e assoli di cerchio e tessuti, aperto a famiglie e amici. Le prove generali sono il sabato precedente.', (current_date + 37), '17:00', '19:00', 'Polisportiva Modena Est', '/images/photos/cerchio-20.webp', 30, (current_date + 25), true),
  ('14920634-3760-5688-8c51-ae5013b84734', '02fd68b1-7a1d-5c30-b563-221d605b1764', 'stage', 'Stage di tessuti con artista ospite', 'Una giornata intensiva con un’artista di circo contemporaneo: sequenze, cadute e creazione di una breve frase coreografica. Riservato ai livelli intermedio e avanzato.', (current_date + 64), '10:00', '16:00', 'Sala Seta — Viale Verdi 186, Modena', '/images/photos/tessuti-30.webp', 10, (current_date + 50), true),
  ('14920634-3760-5688-8c51-ae5013b84734', '8fa33a2b-0844-5297-adaa-f6b5f5cc4841', 'competition', 'Gara regionale UISP di danza aerea', 'Competizione non agonistica a livelli per cerchio e tessuti: esibizione individuale o in duo con valutazione formativa della giuria. Iscrizioni entro la scadenza per organizzare i turni di prova.', (current_date + 52), '09:30', '18:00', 'PalaPanini — Modena', '/images/photos/cerchio-19.webp', 12, (current_date + 30), true),
  ('14920634-3760-5688-8c51-ae5013b84734', 'de1abbee-70e8-523a-95d4-fc54f6fc2f56', 'recital', 'Saggio di fine anno', 'Tutte le classi portano in scena una coreografia di gruppo preparata durante l’anno. Aperto a famiglie e amici.', (current_date + 120), '18:00', '20:30', 'Teatro della Polisportiva Modena Est', '/images/photos/tessuti-31.webp', 60, (current_date + 75), true),
  ('14920634-3760-5688-8c51-ae5013b84734', '112fc487-4433-5726-acf6-5daee82bc5df', 'social', 'Aperitivo di inizio stagione', 'Un momento per conoscersi, presentare le insegnanti e il calendario dell’anno sportivo.', (current_date + -20), '19:30', '22:00', 'Giardino della sede', '/images/photos/tessuti-35.webp', 50, null, true);
