insert into app.announcements (tenant_id, title, body, priority, audience, published_at, is_demo) values
  ('14920634-3760-5688-8c51-ae5013b84734', 'Certificati medici in scadenza', 'Ricordati di controllare la scadenza del tuo certificato medico sportivo nella sezione Profilo: senza certificato valido non è possibile salire sugli attrezzi.', 'important', 'students', (current_date + -1), true),
  ('14920634-3760-5688-8c51-ae5013b84734', 'Prove spettacolo di Natale', 'Le prove di gruppo per lo spettacolo inizieranno a fine mese durante le lezioni intermedie e avanzate. Porta un body scuro e i capelli raccolti.', 'normal', 'all', (current_date + -3), true),
  ('14920634-3760-5688-8c51-ae5013b84734', 'Nuovo tappeto di sicurezza in Sala Seta', 'È arrivato il nuovo crash pad da 20 cm: lo useremo per le prime cadute e le figure avanzate.', 'normal', 'all', (current_date + -8), true),
  ('14920634-3760-5688-8c51-ae5013b84734', 'Registro presenze entro domenica', 'Care insegnanti, ricordate di completare il registro presenze della settimana entro domenica sera.', 'important', 'teachers', (current_date + -2), true);
insert into app.document_types (tenant_id, id, name, category, description, is_required, signature_mode, template_text, validity_months, is_sensitive, is_active) values
  ('14920634-3760-5688-8c51-ae5013b84734', '6588e5ad-ad4f-5d37-b405-1d16314953d9', 'Modulo di iscrizione 2026/27', 'enrollment', 'Modulo firmato con i dati anagrafici e la scelta dei corsi. Scaricalo dai documenti della palestra, firmalo e caricalo.', true, 'upload_signed', null, null, false, true),
  ('14920634-3760-5688-8c51-ae5013b84734', '255d2563-0e32-5925-8684-105051429eae', 'Certificato medico sportivo', 'medical', 'Certificato di idoneità all’attività sportiva non agonistica, valido 12 mesi. Visibile solo a te e alla segreteria.', true, 'none', null, 12, true, true),
  ('14920634-3760-5688-8c51-ae5013b84734', '44500827-6c3f-5906-a4cd-47afe4b275e5', 'Liberatoria attività aeree', 'waiver', 'Dichiarazione di presa visione dei rischi e del regolamento, da firmare direttamente nell’app.', true, 'electronic', 'Dichiaro di aver preso visione del regolamento interno di Oasi Metropolitana e delle norme di sicurezza per la pratica delle discipline aeree (cerchio e tessuti). Mi impegno a seguire le indicazioni delle insegnanti, a segnalare eventuali problemi di salute o infortuni e a non utilizzare gli attrezzi senza supervisione.', null, false, true),
  ('14920634-3760-5688-8c51-ae5013b84734', 'aee15559-aa28-5b90-8814-4e04f944699d', 'Consenso foto e video', 'consent', 'Autorizzazione facoltativa all’uso di foto e video per l’archivio figure e la comunicazione della palestra.', false, 'electronic', 'Autorizzo Oasi Metropolitana a realizzare e conservare fotografie e video durante le lezioni, da usare nell’archivio didattico dell’app (visibile solo agli iscritti) e, previa ulteriore conferma, sui canali di comunicazione dell’associazione. Posso revocare il consenso in qualsiasi momento.', null, false, true),
  ('14920634-3760-5688-8c51-ae5013b84734', 'd17f0367-71d9-585e-9949-61c50606a292', 'Documento d’identità', 'personal', 'Carta d’identità o passaporto, richiesto per il tesseramento.', false, 'none', null, null, false, true);
